-- Sample User and Request rows used by the Request and ENSF 608 test suites.
-- Expected fixture IDs are declared in backend/test/request/seed.ts.
-- Loaded by backend/scripts/request/load-db.sh --test, after db/init (which already
-- has the categories, facilities and the current terms document) and db/request.
-- Left out: the rows db/init already inserts (item_category, recycling_facility,
-- facility_accepts), and the Reward and Notification tables (not this service's).
-- Times are relative to now, so the requests are always in the same state.
BEGIN;
SET search_path TO users, requests, pg_catalog;
SET TIME ZONE 'UTC';





-- 031_user_seed.sql already has version 2, published on a fixed date. Move it to
-- the seed's relative timeline (40 days ago): some requests accepted it 31 days ago.
ON CONFLICT (terms_document_id) DO UPDATE SET published_at = EXCLUDED.published_at;








-- Check every seeded request against the service's own rules (024).
SELECT requests.check_request(p.pickup_request_id) FROM pickup_request p;
COMMIT;
